import{_ as e,o as a,c as d,ah as i}from"./chunks/framework.Yx0DUrwu.js";const m=JSON.parse('{"title":"黏膜免疫、疾病与治疗","description":"","frontmatter":{},"headers":[],"relativePath":"biology/mucosal-disease-immunotherapy.md","filePath":"biology/mucosal-disease-immunotherapy.md","lastUpdated":1787828013000}'),o={name:"biology/mucosal-disease-immunotherapy.md"};function r(l,t,n,c,s,h){return a(),d("div",null,[...t[0]||(t[0]=[i('<h1 id="黏膜免疫、疾病与治疗" tabindex="-1">黏膜免疫、疾病与治疗 <a class="header-anchor" href="#黏膜免疫、疾病与治疗" aria-label="Permalink to &quot;黏膜免疫、疾病与治疗&quot;">​</a></h1><p>免疫系统既要清除威胁，也要避免对自身组织、食物抗原和共生微生物产生过度反应。黏膜免疫、免疫缺陷、过敏、自身免疫、移植、疫苗和肿瘤免疫治疗，本质上都围绕这个平衡展开 [1]。</p><h2 id="黏膜免疫" tabindex="-1">黏膜免疫 <a class="header-anchor" href="#黏膜免疫" aria-label="Permalink to &quot;黏膜免疫&quot;">​</a></h2><p>黏膜是免疫系统最繁忙的界面之一：它持续接触食物、空气、共生菌和病原体。黏膜免疫的重点不是“一直强烈炎症”，而是屏障保护、IgA、组织驻留细胞、微生物群调控和 oral tolerance 的平衡。</p><table tabindex="0"><thead><tr><th>模块</th><th>功能</th><th>单细胞线索</th></tr></thead><tbody><tr><td>epithelial barrier</td><td>物理隔离、抗菌分子、危险信号释放。</td><td>epithelial stress, <code>DEFA*</code>, <code>REG*</code>, interferon genes。</td></tr><tr><td>secretory IgA</td><td>中和和限制微生物黏附，降低炎症性清除需求。</td><td><code>JCHAIN</code>, <code>IGHA1</code>, <code>IGHA2</code>, plasma cells。</td></tr><tr><td>tissue-resident lymphocytes</td><td>快速局部保护与组织监视。</td><td><code>ITGAE</code>, <code>CXCR6</code>, <code>ZNF683</code>, <code>CD69</code>。</td></tr><tr><td>microbiota regulation</td><td>塑造局部和系统免疫状态。</td><td>myeloid activation, Th17/ILC3 program, barrier genes。</td></tr></tbody></table><h2 id="免疫防御失败" tabindex="-1">免疫防御失败 <a class="header-anchor" href="#免疫防御失败" aria-label="Permalink to &quot;免疫防御失败&quot;">​</a></h2><p>免疫缺陷可以来自遗传缺陷、感染、药物、营养、年龄或治疗造成的继发性免疫抑制。不同缺陷对应不同感染谱：</p><table tabindex="0"><thead><tr><th>缺陷类型</th><th>易感问题</th><th>机制理解</th></tr></thead><tbody><tr><td>T cell / combined immunodeficiency</td><td>viral, fungal, opportunistic infections</td><td>T cell help、细胞毒性和免疫协调不足。</td></tr><tr><td>B cell / antibody deficiency</td><td>extracellular bacteria, some viruses</td><td>中和、opsonization 和 complement activation 不足。</td></tr><tr><td>phagocyte defects</td><td>bacterial and fungal dissemination</td><td>摄取、氧爆发或趋化迁移不足。</td></tr><tr><td>complement defects</td><td>encapsulated bacteria, immune complex disease</td><td>opsonization、裂解和免疫复合物清除不足。</td></tr></tbody></table><h2 id="过敏和超敏反应" tabindex="-1">过敏和超敏反应 <a class="header-anchor" href="#过敏和超敏反应" aria-label="Permalink to &quot;过敏和超敏反应&quot;">​</a></h2><p>过敏可以理解为免疫系统对无害抗原产生了过强或错误类型的效应应答。IgE-mediated allergy 中，Th2/Tfh 信号推动 IgE 产生；IgE 固定在 mast cells 和 basophils 的 Fc epsilon receptor 上，再次遇到 allergen 时快速脱颗粒。</p><div class="check-grid"><article><strong>IgE / mast cell axis</strong><span>快速释放 histamine、lipid mediators 和 cytokines，造成鼻炎、哮喘、荨麻疹或 anaphylaxis。</span></article><article><strong>Eosinophils</strong><span>参与寄生虫防御，也可在过敏性炎症中造成组织损伤。</span></article><article><strong>Immune complex</strong><span>大量难清除抗原-抗体复合物可诱发补体和炎症损伤。</span></article><article><strong>Delayed-type hypersensitivity</strong><span>Th1 和 CD8 T cells 可介导迟发型组织炎症。</span></article></div><h2 id="自身免疫和移植" tabindex="-1">自身免疫和移植 <a class="header-anchor" href="#自身免疫和移植" aria-label="Permalink to &quot;自身免疫和移植&quot;">​</a></h2><p>自身免疫来自耐受机制被突破：遗传易感、MHC、感染、组织损伤、分子模拟、免疫豁免区暴露、随机克隆事件都可能参与。移植免疫则是免疫系统把同种异体 MHC 或其呈递的 peptide 识别为危险信号。</p><table tabindex="0"><thead><tr><th>场景</th><th>核心机制</th><th>单细胞关注点</th></tr></thead><tbody><tr><td>organ-specific autoimmunity</td><td>自身抗原局部靶向。</td><td>autoreactive T/B cells, tissue-resident inflammation。</td></tr><tr><td>systemic autoimmunity</td><td>immune complex、广泛炎症和多器官损伤。</td><td>plasmablast expansion, interferon program, myeloid activation。</td></tr><tr><td>acute rejection</td><td>T cell-mediated alloreactivity。</td><td>cytotoxic T cells, APC activation, endothelial inflammation。</td></tr><tr><td>chronic rejection</td><td>持续低度损伤、血管和纤维化改变。</td><td>macrophage/fibroblast/endothelial states。</td></tr></tbody></table><h2 id="疫苗和肿瘤免疫治疗" tabindex="-1">疫苗和肿瘤免疫治疗 <a class="header-anchor" href="#疫苗和肿瘤免疫治疗" aria-label="Permalink to &quot;疫苗和肿瘤免疫治疗&quot;">​</a></h2><p>疫苗的目标是安全地产生长期保护性免疫，通常需要抗原、合适的递送方式、佐剂和记忆细胞形成。肿瘤免疫治疗则利用或增强抗肿瘤免疫，包括 monoclonal antibodies、checkpoint blockade、CAR-T cells 和 cancer vaccines。</p><div class="doc-callout important"><strong>肿瘤免疫治疗看的是系统</strong><p>checkpoint blockade 是否有效，不只取决于 T cell 是否表达 PD-1，还取决于 antigen presentation、T cell infiltration、Treg 和 myeloid suppression、肿瘤抗原负荷、空间排斥和组织代谢环境。</p></div><h2 id="自检问题" tabindex="-1">自检问题 <a class="header-anchor" href="#自检问题" aria-label="Permalink to &quot;自检问题&quot;">​</a></h2><ol><li>黏膜免疫为什么必须同时容忍共生菌和清除病原体？</li><li>不同免疫缺陷为什么对应不同感染谱？</li><li>IgE-mediated allergy 的致敏阶段和效应阶段有什么区别？</li><li>checkpoint blockade 为什么不是只看 <code>PDCD1</code> 或 <code>CD274</code> 表达？</li></ol><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><p>[1] Murphy, K. &amp; Weaver, C. <em>Janeway&#39;s Immunobiology</em>. 9th ed. Garland Science (2017). 中文版：《詹韦免疫生物学：原书第九版》，科学出版社，2022。</p>',21)])])}const u=e(o,[["render",r]]);export{m as __pageData,u as default};
